    rng=(x.high-x.low).replace(0,np.nan); f=-(x.close-x.low)/rng; y=x.close.shift(-1)/x.close-1
    for dt in x.index:
        if pd.notna(f.loc[dt]) and pd.notna(y.loc[dt]): rows.append((dt,s,f.loc[dt],y.loc[dt]))
