import pandas as pd, numpy as np, glob
from scipy.stats import spearmanr
assets=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
ret={}
for a in assets:
 d=pd.read_csv('../persistent/stock_data/'+a+'.csv',parse_dates=['date']).sort_values('date')
 r=d.set_index('date').close.pct_change()
 # low recent volatility relative to medium volatility; only information through t
 f=-(r.rolling(5,min_periods=5).std()/r.rolling(20,min_periods=15).std())
 ret[a]=pd.DataFrame({'f':f,'y':r.shift(-1)})
rows=[]
for dt in sorted(set().union(*[x.index for x in ret.values()])):
 vals=[]; ys=[]
 for a in assets:
  z=ret[a].loc[dt] if dt in ret[a].index else None
  if z is not None and np.isfinite(z.f) and np.isfinite(z.y): vals.append(z.f);ys.append(z.y)
 if len(vals)>=8: rows.append((dt,spearmanr(vals,ys).statistic,len(vals)))
x=pd.DataFrame(rows,columns=['date','ic','n']).set_index('date')
print('dates',len(x),'avg_n',x.n.mean(),'coverage',x.n.mean()/15)
print('IC %.6f ICIR %.6f hit %.4f turnover_proxy %.4f'%(x.ic.mean(),x.ic.mean()/x.ic.std(),(x.ic>0).mean(),np.nan))
for lo,hi in [('2020','2022'),('2023','2024'),('2025','2026'),('2026-07','2027')]:
 z=x.loc[lo:hi].ic; print(lo, 'dates',len(z),'IC %.6f ICIR %.6f'%(z.mean(),z.mean()/z.std()) if len(z) else '')
for h in [3,5,10]:
 # reconstruct forward cumulative returns
 rr=[]
 for dt in x.index:
  vals=[];ys=[]
  for a in assets:
   q=ret[a];
   if dt not in q.index: continue
   f=q.loc[dt].f; prices=pd.read_csv('../persistent/stock_data/'+a+'.csv',parse_dates=['date']).set_index('date').close
   if not np.isfinite(f) or dt not in prices.index: continue
   ix=prices.index.get_loc(dt)
   if ix+h>=len(prices):continue
   y=prices.iloc[ix+h]/prices.iloc[ix]-1
   if np.isfinite(y): vals.append(f);ys.append(y)
  if len(vals)>=8: rr.append(spearmanr(vals,ys).statistic)
 print('h',h,'dates',len(rr),'IC %.6f ICIR %.6f'%(np.mean(rr),np.mean(rr)/np.std(rr)))
# signal artifact
out=[]
for a in assets:
 q=ret[a].copy(); q['asset']=a; q=q.reset_index().rename(columns={'index':'date'}); out.append(q[['date','asset','f']])
pd.concat(out).to_csv('../persistent/factor_signals_miner_3_20270114_vol_compression.csv',index=False)

